"""A Class for performing sequenced interactions to register a new patient on a MOSAIQ application"""

from ..interactions import new_patient_reg
from ..interactions import chart
from ..interactions import dashboard
from ..interactions import d_and_i
from ..interactions import diagnoses_problems_and_staging
from ..interactions import site_setup_definition
from ..interactions import radiation_prescriptions
from ..interactions import dcmtree
from ..interactions import embedded_explorer
from ..interactions import ro_treat
from ..interactions import storescu

class NewPatientRegistration():
    def __init__(self) -> None:
        pass

    def __set_dcmtree_as_app_context_and_foreground(self) -> None:
        dcmtree.set_dcmtree_application_as_context()
        dcmtree.set_dcmtree_application_to_foreground()

    def register_standardPatient(self, patientLastName: str, patientFirstName: str, patientMRNumber: str, physicianName: str, diagnosis: str) -> None:
        dashboard.open_new_patient_registration()
        new_patient_reg.typeText_in_patient_last_name(patientLastName)
        new_patient_reg.typeText_in_patient_first_name(patientFirstName)
        new_patient_reg.typeText_in_patient_mr_number(patientMRNumber)
        new_patient_reg.navigate_to_Physicians_Diagnosis_tab()
        new_patient_reg.typeText_in_attending_physician(physicianName)
        new_patient_reg.open_select_attending_physician_window()
        new_patient_reg.select_physician_from_entire_list(physicianName)
        new_patient_reg.typeText_in_diagnosis(diagnosis)
        new_patient_reg.click_diagnosis_option(diagnosis)
        new_patient_reg.click_save_patient_button()
        new_patient_reg.click_no_NoDuplicatePatients()

    def add_diagnosis_to_patient(self, patientLastName: str, diagnose: str) -> None:
        dashboard.open_patient_d_and_i(patientLastName)
        d_and_i.open_diagnoses_and_problems_window()
        diagnoses_problems_and_staging.open_diagnosis_and_staging_window()
        diagnoses_problems_and_staging.type_in_diagnoses_field_and_confirm(diagnose)
        diagnoses_problems_and_staging.click_save_and_affirm_diagnosis()

    def save_and_affirm_diagnosis(self, patientLastName: str) -> None:
        dashboard.open_patient_chart(patientLastName)
        chart.click_diagnosis_and_problems_tab_item()
        chart.click_diagnoses_and_problems_grid_object()
        chart.click_diagnoses_and_problems_change_button()
        chart.click_diagnoses_and_staging_save_and_affirm_button()

    def add_dicom_files_to_dcmtree(self, target_x: int, target_y: int) -> None:
        fileListObjects = embedded_explorer.get_file_list_children()
        embedded_explorer.click_list_item(fileListObjects[-1])
        embedded_explorer.shift_click_list_item(fileListObjects[2]) # type: ignore
        embedded_explorer.drag_from_explorer(fileListObjects[2], target_x, target_y) # type: ignore

    def transmit_plan_via_dcmtree_to_local_scp(self) -> None:
        dcmtree.open_transmit_dialog()
        dcmtree.type_ae_title_in_transmit_dialog("IMPAC_DCM_SCP")
        dcmtree.type_host_name_in_transmit_dialog("localhost")
        dcmtree.type_port_number_in_transmit_dialog("106")
        dcmtree.click_send_button()
        dcmtree.wait_for_completed_transmission()

    def send_dicom_data_via_storescu(self, dicomDataFolderPath: str) -> None:
        storescu.send_dicom_data(dicomDataFolderPath)

    def promote_plan(self, patientLastName: str) -> None:
        dashboard.open_patient_chart(patientLastName)
        chart.click_tx_plans_tab_item()
        chart.click_tx_plans_promote_plan_button()
        chart.click_treatment_plan_promote_button()

    def site_setup(self) -> None:
        d_and_i.double_click_site_setup_in_list_view()
        site_setup_definition.enter_site_setup_verification('Verify')
        site_setup_definition.enter_site_setup_accessory("Breast Board")
        site_setup_definition.enter_site_setup_accessory("Chair")
        site_setup_definition.enter_site_setup_tolerance("Clinical SS")
        site_setup_definition.click_site_setup_approve()
        site_setup_definition.enter_site_setup_approval_password("impac")
        site_setup_definition.click_site_setup_approval_ok_button()

    def complete_rad_rx(self) -> None:
        d_and_i.select_radiation_in_list_view()
        d_and_i.open_rad_rx_window()
        radiation_prescriptions.click_rad_rx_change_button()
        radiation_prescriptions.click_rad_rx_fractionation_pattern_dropdown()
        radiation_prescriptions.click_rad_rx_wave_setup_form_ok_button()
        radiation_prescriptions.click_rad_rx_ok_button()
        radiation_prescriptions.click_rad_rx_close_button()

    def process_dosimetry(self) -> None:
        d_and_i.click_dandi_dosimetry_button()
        d_and_i.click_dosimetry_setup_close_button()
        d_and_i.click_close_d_and_i()

    def ro_treat_calendar(self, patientLastName: str) -> None:
        dashboard.open_patient_ro_treat(patientLastName)
        ro_treat.open_tx_calendar()
        ro_treat.select_course_one_prescription()
        ro_treat.click_insert_sessions_button()
        ro_treat.clear_insert_sessions_dialog()

    def ro_treat_schedule_fields(self) -> None:
        ro_treat.click_schedule_all_fields()
        ro_treat.click_fields_to_be_scheduled_add_all_button()
        ro_treat.click_fields_to_be_scheduled_ok_button()
        ro_treat.click_schedule_fields_button()

    def ro_treat_set_treatment_status(self, password: str) -> None:
        ro_treat.open_treatment_status()
        ro_treat.select_approved_status_in_record_status()
        ro_treat.enter_record_status_signature_password(password=password)
        ro_treat.click_record_status_ok_button()
        ro_treat.click_close_patient_ro_treat()
